// todo.store.ts
export interface Todo { id: number; title: string; completed: boolean; }

@Injectable({ providedIn: 'root' })
export class TodoStore {
  private todosSubject = new BehaviorSubject<Todo[]>([]);
  todos$ = this.todosSubject.asObservable();

  completedCount$ = this.todos$.pipe(
    map(todos => todos.filter(t => t.completed).length),
    distinctUntilChanged()
  );

  addTodo(title: string) {
    const newTodo: Todo = { id: Date.now(), title, completed: false };
    this.todosSubject.next([...this.todosSubject.value, newTodo]);
  }

  removeTodo(id: number) {
    const todos = this.todosSubject.value.filter(t => t.id !== id);
    this.todosSubject.next(todos);
  }

  toggleTodo(id: number) {
    const todos = this.todosSubject.value.map(t =>
      t.id === id ? { ...t, completed: !t.completed } : t
    );
    this.todosSubject.next(todos);
  }
}

// todo-summary.component.ts
@Component({...})
export class TodoSummaryComponent {
  constructor(public store: TodoStore) {}
}
